engine.analyze:
async function analyze(input, providers) {
  var tools = (await providers.tools.list()) || [];
  var dataBundles = providers.tools.listData ? (await providers.tools.listData()) || [] : [];
  var user = providers.tools.userIdentity ? providers.tools.userIdentity() : {};

  // 2026-05-16: audience filter dropped from Data Hub per user request —
  // show ALL bundles (including admin/audience-restricted ones) so the
  // user can see everything that exists in the manifest, not just what
  // their identity unlocks for dashboard tiles. The audience filter still
  // gates DASHBOARD VISIBILITY in the kernel; Data Hub is the catalog
  // view and should be exhaustive.
  var visibleTools = tools.filter(function (t) {
    if (!t || !t.id) return false;
    if (String(t.id).charAt(0) === "_") return false;
    return true;
  });

  visibleTools.sort(function (a, b) {
    var ca = (a.catalog && a.catalog.category) || "Other";
    var cb = (b.catalog && b.catalog.category) || "Other";
    if (ca !== cb) return String(ca).localeCompare(String(cb));
    var oa = (a.catalog && a.catalog.order) || 999;
    var ob = (b.catalog && b.catalog.order) || 999;
    if (oa !== ob) return oa - ob;
    return String(a.label || a.id).localeCompare(String(b.label || b.id));
  });

  var menuVis = providers.menuVis || {};
  var toolRows = visibleTools.map(function (t) {
    var visOverride = menuVis[(t.catalog && t.catalog.id) || t.id] || "";
    var hidden = visOverride === "hide" || (visOverride !== "show" && !!(t.catalog && t.catalog.hidden));
    return {
      kind: "tool",
      id: t.id,
      label: t.label || t.id,
      icon: (t.catalog && t.catalog.icon) || "🛠️",
      category: (t.catalog && t.catalog.category) || "Other",
      releasedAt: t.releasedAt || t.installedAt || null,
      tier: t.tier || "demand",
      // A bundle is v3 if it has ANY v3 shape marker. Previously this
      // only checked engine/view/advertises.tile — that flagged tools
      // like eli_settings (init.js + css, no tile because it's hidden)
      // and any tool whose tile lives under a different advertises
      // channel (legal_risks → tile: app_legal_risks) as V2 in the UI.
      isV3: !!(
        t.engine || t.view || t.init || t.css ||
        (t.advertises && typeof t.advertises === "object" && Object.keys(t.advertises).length)
      ),
      enabled: !t.disabled,
      hidden: hidden,
      core: !!(t.catalog && t.catalog.core),
    };
  });

  // Cross-reference data stamps against manifest entries for label + filename.
  var manifest = null;
  try {
    if (providers.tools.getCachedManifest) manifest = await providers.tools.getCachedManifest();
  } catch (e) {}
  var manifestById = {};
  if (manifest && Array.isArray(manifest.tools)) {
    manifest.tools.forEach(function (e) { manifestById[e.id] = e; });
  }

  // Friendly labels for known proprietary libraries. Recognizes both
  // canonical (snake_case) AND legacy (camelCase) IDs since earlier
  // versions of the install path produced the camelCase form.
  var KNOWN_LIB_LABELS = {
    "__data_bd_templates":     "Build Draft Templates",
    "__data_bdTemplates":      "Build Draft Templates",
    "__data_playbooks":        "Negotiation Playbooks",
    "__data_riskRules":        "Risk Rules Library",
    "__data_risk_rules":       "Risk Rules Library",
    "__data_requesters":       "Requesters Directory",
    "__data_requesters_enc":   "Requesters Directory",
    "__data_templates":        "Document Templates",
    "__data_team_commentary":  "Team Commentary",
    "__data_teamCommentary":   "Team Commentary",
  };
  // Aliases from legacy (camelCase) → canonical (snake_case) ids. When
  // the user's installed stamp is camelCase but the manifest now uses
  // snake_case (or vice versa), we cross-ref under both keys so the row
  // gets a `manifestEntry` and shows as cdnTracked.
  var ID_ALIASES = {
    "__data_bdTemplates":    "__data_bd_templates",
    "__data_riskRules":      "__data_risk_rules",
    "__data_teamCommentary": "__data_team_commentary",
    "__data_requesters":     "__data_requesters_enc",
  };

  var dataRows = dataBundles.map(function (d) {
    // Try direct id, then alias lookup so legacy camelCase installs
    // still match snake_case manifest entries.
    var entry = manifestById[d.id] || (ID_ALIASES[d.id] && manifestById[ID_ALIASES[d.id]]) || null;
    var label = (entry && entry.label)
              || KNOWN_LIB_LABELS[d.id]
              || d.id.replace(/^__data_/, "").replace(/^_/, "");
    var cdnTracked = !!(entry && entry.filename);
    // Encrypted = source flag OR manifest says encrypted OR id maps to
    // a known encrypted library. Catches legacy installs that didn't
    // record the source field properly.
    var fromEncrypted = d.source === "encrypted_library"
      || !!(entry && entry.encrypted)
      || /^__data_(bd_templates|bdTemplates|playbooks|riskRules|risk_rules|templates|requesters|requesters_enc|team_commentary|teamCommentary)$/.test(d.id);
    return {
      kind: "data",
      id: d.id,
      label: label,
      icon: fromEncrypted ? "🔐" : (cdnTracked ? "📚" : "🔒"),
      sourceTag: fromEncrypted ? "ENCRYPTED" : (cdnTracked ? "CDN" : "LOCAL"),
      category: "Data Libraries",
      releasedAt: d.releasedAt,
      fetchedAt: d.fetchedAt,
      source: d.source,
      cdnTracked: cdnTracked,
      fromEncrypted: fromEncrypted,
      manifestEntry: entry,
    };
  });

  // Dedupe legacy-stamp duplicates. When BOTH a legacy (camelCase) stamp
  // and its canonical (snake_case) equivalent live in STORE_CONFIG — a
  // residue of earlier install paths — engine prior to this change emitted
  // two rows for the same library (one tagged LOCAL because the manifest
  // didn't list the camelCase id, one tagged CDN). Drop the legacy row from
  // the UI AND flag the stale stamp so init.js can clean STORE_CONFIG.
  // Only legacy stamps whose canonical equivalent is ALSO installed are
  // pruned — a truly local-only upload with a non-aliased id stays visible.
  var installedDataIds = {};
  dataRows.forEach(function (r) { installedDataIds[r.id] = true; });
  var redundantLegacyDataIds = [];
  // Phantom stamps that point at tool/system stores (jsonTools → json_tools,
  // etc.). A pre-fix master-package upload could write _data_jsonTools to
  // STORE_CONFIG, making the data list show a "jsonTools LOCAL" row with
  // no real library behind it. Clicking Uninstall would clearStore('json_tools')
  // — wiping every installed tool. Pull these out of the UI entirely and
  // flag them for stamp-only cleanup in init.js.
  var phantomToolDataIds = [];
  var PHANTOM_DANGEROUS_IDS = {
    "jsonTools": true,
    "json_tools": true,
    "__data_jsonTools": true,
    "__data_json_tools": true,
  };
  dataRows = dataRows.filter(function (r) {
    if (PHANTOM_DANGEROUS_IDS[r.id]) {
      phantomToolDataIds.push(r.id);
      return false;
    }
    var canonical = ID_ALIASES[r.id];
    if (canonical && installedDataIds[canonical]) {
      redundantLegacyDataIds.push(r.id);
      return false;
    }
    return true;
  });

  // Order data libraries: encrypted (proprietary) first, then everything
  // else; alphabetical by label within each group. Encrypted libs are
  // the most consequential to install/uninstall, so they read top-of-list.
  dataRows.sort(function (a, b) {
    if (a.fromEncrypted !== b.fromEncrypted) return a.fromEncrypted ? -1 : 1;
    return String(a.label || "").localeCompare(String(b.label || ""));
  });

  // Row count per data library — sum of rows across every section store
  // the lib populates. Manifest section names can be camelCase
  // (bdTemplates) or snake_case (bd_templates); _toStore normalizes to
  // the actual STORE_* name. Libraries with no manifest entry (LOCAL
  // uploads) skip — we don't know which stores they wrote to.
  if (providers.storage && typeof providers.storage.count === "function") {
    var SECTION_TO_STORE = {
      jsonTools: "json_tools",
      agreementTypes: "agreement_types",
      riskRules: "risk_rules",
      emailTemplates: "email_templates",
      loadingMsgs: "loading_msgs",
      cleanerRules: "cleaner_rules",
      execBriefTerms: "exec_brief_terms",
      teamCommentary: "team_commentary",
      bdTemplates: "bd_templates",
    };
    await Promise.all(dataRows.map(async function (r) {
      var entry = r.manifestEntry;
      if (!entry || !Array.isArray(entry.sections) || !entry.sections.length) return;
      var stores = {};
      entry.sections.forEach(function (s) {
        var store = SECTION_TO_STORE[s] || s;
        if (store) stores[store] = true;
      });
      var counts = await Promise.all(Object.keys(stores).map(function (s) {
        return providers.storage.count(s).catch(function () { return 0; });
      }));
      r.rowCount = counts.reduce(function (sum, n) { return sum + (n || 0); }, 0);
    }));
  }

  var byCategory = {};
  toolRows.forEach(function (r) {
    if (!byCategory[r.category]) byCategory[r.category] = [];
    byCategory[r.category].push(r);
  });
  if (dataRows.length) {
    byCategory["Data Libraries"] = dataRows;
  }

  // Bundles — manifest-defined packs that group tools + data libs as
  // a single install/uninstall unit. Compute installation status by
  // counting how many members are present in the local installs.
  var bundles = [];
  if (manifest && Array.isArray(manifest.bundles)) {
    var installedToolIds = {};
    tools.forEach(function (t) { if (t && t.id) installedToolIds[t.id] = true; });
    var installedDataIds = {};
    dataBundles.forEach(function (d) {
      if (!d || !d.id) return;
      installedDataIds[d.id] = true;
      // Aliases (legacy camelCase ↔ snake_case) — count matched.
      if (ID_ALIASES[d.id]) installedDataIds[ID_ALIASES[d.id]] = true;
    });
    bundles = manifest.bundles
      .filter(function (b) {
        return b && b.id && Array.isArray(b.members) && b.members.length;
      })
      // 2026-05-16: audience filter dropped on bundles too — Data Hub
      // shows every published bundle (including admin) so power users
      // can see the full catalog.
      .map(function (b) {
        var memberDetails = b.members.map(function (memberId) {
          var isData = String(memberId).indexOf("__data_") === 0;
          var installed = isData
            ? !!installedDataIds[memberId]
            : !!installedToolIds[memberId];
          var entry = manifestById[memberId] || null;
          return {
            id: memberId,
            kind: isData ? "data" : "tool",
            label: (entry && entry.label) || KNOWN_LIB_LABELS[memberId] || memberId,
            icon: (entry && entry.catalog && entry.catalog.icon) || (isData ? "📦" : "🛠️"),
            // Tool category from manifest (release_tools.js stamps it on each
            // entry from catalog.category). Data libs get a single bucket;
            // view groups them at the bottom under "Data Libraries".
            category: isData
              ? "Data Libraries"
              : ((entry && (entry.category || (entry.catalog && entry.catalog.category))) || "Other"),
            installed: installed,
          };
        });
        // Order: tools first, alpha by category then label; data libs last
        // (their category is "Data Libraries" which sorts naturally but we
        // force it via the kind flag so a tool category named "Z…" can't
        // accidentally fall below libraries).
        memberDetails.sort(function (a, b) {
          if (a.kind !== b.kind) return a.kind === "data" ? 1 : -1;
          if (a.category !== b.category) return String(a.category).localeCompare(String(b.category));
          return String(a.label).localeCompare(String(b.label));
        });
        var installedCount = memberDetails.filter(function (m) { return m.installed; }).length;
        return {
          id: b.id,
          label: b.label || b.id,
          icon: b.icon || "📦",
          description: b.description || "",
          members: memberDetails,
          installedCount: installedCount,
          totalCount: memberDetails.length,
          fullyInstalled: installedCount === memberDetails.length,
        };
      });
  }

  return {
    items: toolRows.concat(dataRows),
    byCategory: byCategory,
    bundles: bundles,
    overview:
      toolRows.length + " tool" + (toolRows.length === 1 ? "" : "s") +
      " · " + dataRows.length + " data lib" + (dataRows.length === 1 ? "" : "s") +
      (bundles.length ? " · " + bundles.length + " bundle" + (bundles.length === 1 ? "" : "s") : ""),
    toolCount: toolRows.length,
    dataCount: dataRows.length,
    bundleCount: bundles.length,
    // Stale-stamp ids whose canonical equivalent is installed. init.js
    // deletes these from STORE_CONFIG opportunistically on open so the
    // dedupe is persistent, not just a UI filter.
    redundantLegacyDataIds: redundantLegacyDataIds,
    // Phantom data stamps that resolve to STORE_JSON_TOOLS (or other
    // tool-bearing stores). init.js prunes the stamp only — never the
    // section data — so a legacy master-package upload artifact can't
    // wipe every installed tool through the UI.
    phantomToolDataIds: phantomToolDataIds,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: (window.eli && window.eli.tools && window.eli.tools._loaded && window.eli.tools._loaded.tool_manager && window.eli.tools._loaded.tool_manager.releasedAt) || "unknown",
      docHash: null,
      timestamp: Date.now(),
    },
  };
}

view.renderMasterExportPicker:
function renderMasterExportPicker(opts) {
  var rows = opts.rows || [];
  var onConfirm = opts.onConfirm || function () {};
  var onCancel = opts.onCancel || function () {};
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  var groups = { tools: [], data: [] };
  rows.forEach(function (r) {
    if (r.kind === "data") groups.data.push(r);
    else groups.tools.push(r);
  });
  function _itemRow(r) {
    var icon = r.icon || (r.kind === "data" ? "📚" : "🛠️");
    var meta = r.kind === "data" && typeof r.rowCount === "number"
      ? ' · ' + r.rowCount.toLocaleString() + ' row' + (r.rowCount === 1 ? '' : 's')
      : "";
    return '<label class="_eli3_tm_pick_row">' +
      '<input type="checkbox" data-eli-tm-export-pick="' + _esc(r.id) + '" data-eli-tm-export-kind="' + _esc(r.kind) + '" checked>' +
      '<span class="_eli3_tm_pick_row_icon">' + _esc(icon) + '</span>' +
      '<span class="_eli3_tm_pick_row_label">' + _esc(r.label) + '</span>' +
      '<span class="_eli3_tm_pick_id">' + _esc(r.id) + _esc(meta) + '</span>' +
    '</label>';
  }
  function _section(title, items, key) {
    if (!items.length) return "";
    return '<div class="_eli3_tm_pick_section">' +
      '<button class="_eli3_tm_pick_section_head" type="button" data-eli-tm-collapse-head="' + _esc(key) + '">' +
        '<span class="_eli3_tm_pick_section_chevron">▸</span>' +
        '<span class="_eli3_tm_pick_section_title">' + _esc(title) + '</span>' +
        '<span class="_eli3_tm_pick_section_count">' + items.length + '</span>' +
      '</button>' +
      '<div class="_eli3_tm_pick_section_body" data-eli-tm-collapse-body="' + _esc(key) + '" style="display:none">' +
        items.map(_itemRow).join("") +
      '</div>' +
    '</div>';
  }
  var bodyHtml =
    '<div class="_eli3_tm_pick_intro">' +
      'Tick what you want bundled into a master JSON. Result copies to clipboard — paste into <code>eli-master-&lt;date&gt;.json</code>.' +
    '</div>' +
    '<div class="_eli3_tm_pick_quickactions">' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_export_all">Select all</button>' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_export_none">Clear all</button>' +
    '</div>' +
    _section("Tools", groups.tools, "tools") +
    _section("Data Libraries", groups.data, "data");
  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_tm_pick_dialog",
    icon: "📤",
    title: "Export Master JSON",
    body: bodyHtml,
    primary: {
      label: "📤 Export to clipboard",
      onclick: function (e, ov) {
        var picks = { tools: [], data: [] };
        ov.querySelectorAll("[data-eli-tm-export-pick]:checked").forEach(function (cb) {
          var id = cb.getAttribute("data-eli-tm-export-pick");
          var kind = cb.getAttribute("data-eli-tm-export-kind");
          (kind === "data" ? picks.data : picks.tools).push(id);
        });
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        onConfirm(picks);
      },
    },
    secondary: { label: "Cancel", onclick: function () { onCancel(); } },
    onMount: function (overlay) {
      overlay.querySelector("#_eli3_tm_export_all").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-export-pick]").forEach(function (cb) { cb.checked = true; });
      };
      overlay.querySelector("#_eli3_tm_export_none").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-export-pick]").forEach(function (cb) { cb.checked = false; });
      };
      overlay.querySelectorAll("[data-eli-tm-collapse-head]").forEach(function (head) {
        head.onclick = function () {
          var key = head.getAttribute("data-eli-tm-collapse-head");
          var body = overlay.querySelector('[data-eli-tm-collapse-body="' + key + '"]');
          var chev = head.querySelector("._eli3_tm_pick_section_chevron");
          if (!body) return;
          var open = body.style.display !== "none";
          body.style.display = open ? "none" : "";
          if (chev) chev.textContent = open ? "▸" : "▾";
        };
      });
    },
  });
}

view.renderReinstallPicker:
function renderReinstallPicker(opts) {
  var rows = opts.rows || []; // [{id, label, kind, icon, cdnTracked}]
  var onConfirm = opts.onConfirm || function () {};
  var onCancel = opts.onCancel || function () {};
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }
  // Group by kind for readability. Local-only libraries (not in CDN
  // manifest) are excluded from the picker entirely — they can't be
  // force-reinstalled from CDN. User uses Upload File to re-import them.
  var groups = { tools: [], data: [] };
  rows.forEach(function (r) {
    if (r.kind === "data" && r.cdnTracked === false) return; // skip local
    if (r.kind === "data") groups.data.push(r);
    else groups.tools.push(r);
  });

  function _itemRow(r, disabled) {
    var cb = disabled
      ? '<span class="_eli3_tm_pick_row_lock" title="Re-import required">🔒</span>'
      : '<input type="checkbox" data-eli-tm-pick="' + _esc(r.id) + '" checked>';
    var icon = r.icon || (r.kind === "data" ? "📚" : "🛠️");
    return '<label class="_eli3_tm_pick_row' + (disabled ? ' _eli3_tm_pick_row_disabled' : '') + '">' +
      cb +
      '<span class="_eli3_tm_pick_row_icon">' + _esc(icon) + '</span>' +
      '<span class="_eli3_tm_pick_row_label">' + _esc(r.label) + '</span>' +
      '<span class="_eli3_tm_pick_id">' + _esc(r.id) + '</span>' +
    '</label>';
  }
  function _section(title, sub, items, disabled, key) {
    if (!items.length) return "";
    return '<div class="_eli3_tm_pick_section" data-eli-tm-collapse="' + _esc(key) + '">' +
      '<button class="_eli3_tm_pick_section_head" type="button" data-eli-tm-collapse-head="' + _esc(key) + '">' +
        '<span class="_eli3_tm_pick_section_chevron">▾</span>' +
        '<span class="_eli3_tm_pick_section_title">' + _esc(title) + '</span>' +
        '<span class="_eli3_tm_pick_section_count">' + items.length + '</span>' +
      '</button>' +
      '<div class="_eli3_tm_pick_section_body" data-eli-tm-collapse-body="' + _esc(key) + '">' +
        (sub ? '<div class="_eli3_tm_pick_section_sub">' + _esc(sub) + '</div>' : "") +
        items.map(function (r) { return _itemRow(r, disabled); }).join("") +
      '</div>' +
    '</div>';
  }

  var bodyHtml =
    '<div class="_eli3_tm_pick_intro">' +
      'Forces a fresh download from CDN for everything you tick. User settings + IDB stats are preserved.' +
    '</div>' +
    '<div class="_eli3_tm_pick_quickactions">' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_pick_all">Select all</button>' +
      '<button class="_eli3_tm_pick_quick" id="_eli3_tm_pick_none">Clear all</button>' +
    '</div>' +
    _section("Tools", null, groups.tools, false, "tools") +
    _section("Data Libraries", null, groups.data, false, "data");

  showEliDialog({
    variant: "info",
    tier: "premium",
    dialogClass: "_eli3_dialog_wide _eli3_tm_pick_dialog",
    icon: "↺",
    title: "Force Reinstall",
    body: bodyHtml,
    primary: {
      label: "Reinstall selected",
      onclick: function (e, ov) {
        var picks = [];
        ov.querySelectorAll("[data-eli-tm-pick]:checked").forEach(function (cb) {
          picks.push(cb.getAttribute("data-eli-tm-pick"));
        });
        if (ov.parentNode) ov.parentNode.removeChild(ov);
        onConfirm(picks);
      },
    },
    secondary: { label: "Cancel", onclick: function () { onCancel(); } },
    onMount: function (overlay) {
      overlay.querySelector("#_eli3_tm_pick_all").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-pick]").forEach(function (cb) { cb.checked = true; });
      };
      overlay.querySelector("#_eli3_tm_pick_none").onclick = function () {
        overlay.querySelectorAll("[data-eli-tm-pick]").forEach(function (cb) { cb.checked = false; });
      };
      // Collapsible section heads.
      overlay.querySelectorAll("[data-eli-tm-collapse-head]").forEach(function (head) {
        head.onclick = function () {
          var key = head.getAttribute("data-eli-tm-collapse-head");
          var body = overlay.querySelector('[data-eli-tm-collapse-body="' + key + '"]');
          var chev = head.querySelector("._eli3_tm_pick_section_chevron");
          if (!body) return;
          var open = body.style.display !== "none";
          body.style.display = open ? "none" : "";
          if (chev) chev.textContent = open ? "▸" : "▾";
        };
      });
    },
  });
}

view.renderManagerPanel:
function renderManagerPanel(opts) {
  var result = opts.result || {};
  var rows = result.items || [];
  var byCategory = result.byCategory || {};
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var onToggleEnabled = opts.onToggleEnabled || function () {};
  var onToggleHidden  = opts.onToggleHidden  || function () {};
  var onForceReinstall = opts.onForceReinstall || function () {};
  var onExport = opts.onExport || function () {};
  var onUninstall = opts.onUninstall || function () {};
  var onCheckUpdates = opts.onCheckUpdates || function () {};
  var onImport = opts.onImport || function () {};
  var onClose = opts.onClose || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function _shortTs(iso) {
    if (!iso) return "—";
    var d = new Date(iso);
    if (isNaN(d.getTime())) return String(iso);
    var months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    var hours = d.getHours();
    var ampm = hours >= 12 ? "pm" : "am";
    hours = hours % 12 || 12;
    var mins = ("0" + d.getMinutes()).slice(-2);
    return months[d.getMonth()] + " " + d.getDate() + " - " + hours + ":" + mins + ampm;
  }

  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_tm_root";

  // Header bar with back arrow + title + actions
  var bar = document.createElement("div");
  bar.className = "_eli3_tm_bar";
  bar.innerHTML =
    '<button class="_eli3_tm_back" title="Back">←</button>' +
    '<div class="_eli3_tm_title">🧩 Data Hub</div>' +
    '<div class="_eli3_tm_overview">' + _esc(result.overview || "") + '</div>';
  bar.querySelector("._eli3_tm_back").onclick = onClose;
  root.appendChild(bar);

  // Action row at top
  var actions = document.createElement("div");
  actions.className = "_eli3_tm_actions";
  function _btn(label, handler, variant) {
    var b = document.createElement("button");
    b.className = "_eli3_tm_action_btn" + (variant ? " " + variant : "");
    b.textContent = label;
    b.onclick = handler;
    return b;
  }
  actions.appendChild(_btn("🔄 Check for Updates", onCheckUpdates));
  actions.appendChild(_btn("↺ Force Reinstall", opts.onReinstallAll || function () {}, "_eli3_tm_action_secondary"));
  // Manual install: paste/drop a single tool OR data bundle JSON. Type is
  // auto-detected. Useful when CDN auto-update is stuck or for offline
  // installs / pre-release testing.
  actions.appendChild(_btn("📥 Upload File", onImport, "_eli3_tm_action_secondary"));
  actions.appendChild(_btn("📤 Export Master", opts.onExportMaster || function () {}, "_eli3_tm_action_secondary"));
  root.appendChild(actions);

  // Category-grouped list, with collapsible top-level sections:
  //   Bundles    (if manifest defines any)
  //   Tools      (one per tool category)
  //   Data Libraries
  var listWrap = document.createElement("div");
  listWrap.className = "_eli3_tm_list";

  var bundles = result.bundles || [];
  if (bundles.length) {
    listWrap.appendChild(_renderCollapseSection({
      id: "bundles",
      title: "Bundles",
      count: bundles.length,
      content: function () {
        var box = document.createElement("div");
        bundles.forEach(function (b) { box.appendChild(_renderBundleRow(b)); });
        return box;
      },
    }));
  }

  // Split byCategory into tool categories vs the special "Data Libraries".
  var dataCat = byCategory["Data Libraries"];
  var toolCats = Object.keys(byCategory).filter(function (c) { return c !== "Data Libraries"; }).sort();

  if (toolCats.length) {
    listWrap.appendChild(_renderCollapseSection({
      id: "tools",
      title: "Tools",
      count: toolCats.reduce(function (sum, c) { return sum + (byCategory[c] || []).length; }, 0),
      content: function () {
        var box = document.createElement("div");
        toolCats.forEach(function (cat) {
          var head = document.createElement("div");
          head.className = "_eli3_tm_cat_head";
          head.textContent = cat;
          box.appendChild(head);
          byCategory[cat].forEach(function (t) { box.appendChild(_renderRow(t)); });
        });
        return box;
      },
    }));
  }

  if (dataCat && dataCat.length) {
    listWrap.appendChild(_renderCollapseSection({
      id: "data",
      title: "Data Libraries",
      count: dataCat.length,
      content: function () {
        var box = document.createElement("div");
        dataCat.forEach(function (d) { box.appendChild(_renderRow(d)); });
        return box;
      },
    }));
  }

  if (!toolCats.length && !(dataCat && dataCat.length) && !bundles.length) {
    var empty = document.createElement("div");
    empty.className = "_eli3_tm_empty";
    empty.textContent = "No tools installed.";
    listWrap.appendChild(empty);
  }

  root.appendChild(listWrap);

  // Build a collapsible section. State is in-memory only (lives on
  // window._eli3_tm_collapsed) — survives panel re-renders within a
  // session but resets on reload. Losing state across reloads costs
  // one click; persisting it via localStorage wasn't worth the bytes.
  function _renderCollapseSection(opts) {
    var sec = document.createElement("div");
    sec.className = "_eli3_tm_section";
    if (!window._eli3_tm_collapsed) window._eli3_tm_collapsed = {};
    var memKey = String(opts.id);
    var isOpen = window._eli3_tm_collapsed[memKey] !== true; // default open
    var head = document.createElement("button");
    head.className = "_eli3_tm_section_head";
    head.innerHTML =
      '<span class="_eli3_tm_section_chevron">' + (isOpen ? "▾" : "▸") + '</span>' +
      '<span class="_eli3_tm_section_title">' + _esc(opts.title) + '</span>' +
      '<span class="_eli3_tm_section_count">' + opts.count + '</span>';
    var body = document.createElement("div");
    body.className = "_eli3_tm_section_body";
    body.appendChild(opts.content());
    if (!isOpen) body.style.display = "none";
    head.onclick = function () {
      isOpen = !isOpen;
      head.querySelector("._eli3_tm_section_chevron").textContent = isOpen ? "▾" : "▸";
      body.style.display = isOpen ? "" : "none";
      window._eli3_tm_collapsed[memKey] = !isOpen;
    };
    sec.appendChild(head);
    sec.appendChild(body);
    return sec;
  }

  function _renderBundleRow(b) {
    var r = document.createElement("div");
    r.className = "_eli3_tm_bundle";
    var pct = b.totalCount ? Math.round(100 * b.installedCount / b.totalCount) : 0;
    var statusLabel = b.fullyInstalled
      ? "✓ Installed"
      : (b.installedCount + " / " + b.totalCount + " installed");
    r.innerHTML =
      '<div class="_eli3_tm_bundle_main">' +
        '<span class="_eli3_tm_bundle_icon">' + _esc(b.icon || "📦") + '</span>' +
        '<div class="_eli3_tm_bundle_info">' +
          '<div class="_eli3_tm_bundle_label">' + _esc(b.label) + '</div>' +
          '<div class="_eli3_tm_bundle_desc">' + _esc(b.description || "") + '</div>' +
        '</div>' +
        '<span class="_eli3_tm_bundle_status' + (b.fullyInstalled ? " _eli3_tm_bundle_status_full" : "") + '">' +
          _esc(statusLabel) +
        '</span>' +
        '<button class="_eli3_tm_kebab" data-eli-tm-bundle-kebab="' + _esc(b.id) + '">⋯</button>' +
      '</div>' +
      '<div class="_eli3_tm_bundle_drawer" data-eli-tm-bundle-drawer="' + _esc(b.id) + '" hidden>' +
        '<div class="_eli3_tm_bundle_members">' +
          (function () {
            // Members are pre-sorted by the engine: tools first (by category,
            // then label), libraries last. Inject a sub-header whenever the
            // category changes so the user sees the grouping.
            var lastCat = null;
            return b.members.map(function (m) {
              var cat = m.category || (m.kind === "data" ? "Data Libraries" : "Other");
              var header = cat !== lastCat
                ? '<div class="_eli3_tm_bundle_subgroup_head">' + _esc(cat) + '</div>'
                : "";
              lastCat = cat;
              return header +
                '<div class="_eli3_tm_bundle_member' + (m.installed ? " _eli3_tm_bundle_member_on" : "") + '">' +
                  '<span class="_eli3_tm_bundle_member_check">' + (m.installed ? "✓" : "○") + '</span>' +
                  '<span class="_eli3_tm_bundle_member_icon">' + _esc(m.icon) + '</span>' +
                  '<span class="_eli3_tm_bundle_member_label">' + _esc(m.label) + '</span>' +
                  '<span class="_eli3_tm_bundle_member_kind">' + (m.kind === "data" ? "DATA" : "TOOL") + '</span>' +
                '</div>';
            }).join("");
          })() +
        '</div>' +
        '<div class="_eli3_tm_bundle_actions">' +
          '<button class="_eli3_tm_action_btn" data-eli-tm-bundle-install="' + _esc(b.id) + '">📦 Install all</button>' +
          '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-bundle-reinstall="' + _esc(b.id) + '">↺ Force reinstall all</button>' +
          '<button class="_eli3_tm_action_btn _eli3_tm_action_danger" data-eli-tm-bundle-uninstall="' + _esc(b.id) + '">🗑 Uninstall all</button>' +
        '</div>' +
      '</div>';
    return r;
  }

  function _renderRow(t) {
    var r = document.createElement("div");
    r.className = "_eli3_tm_row" + (t.enabled === false ? " _eli3_tm_row_disabled" : "");
    var isData = t.kind === "data";
    var rightSide = isData
      // Data rows: kebab only (no toggle — data isn't disable-able).
      ? '<button class="_eli3_tm_kebab" data-eli-tm-kebab="' + _esc(t.id) + '" title="More">⋯</button>'
      : '<label class="_eli3_tm_toggle" title="Enable / disable">' +
          '<input type="checkbox" data-eli-tm-enable="' + _esc(t.id) + '"' + (t.enabled ? " checked" : "") + '>' +
          '<span class="_eli3_tm_toggle_slider"></span>' +
        '</label>' +
        '<button class="_eli3_tm_kebab" data-eli-tm-kebab="' + _esc(t.id) + '" title="More">⋯</button>';
    // Two destructive actions, distinct intent:
    //   ↺ Force re-install — clears + re-syncs from CDN immediately
    //   🗑 Uninstall       — clears only; user clicks Check for Updates
    //                         later to bring it back (or re-import for
    //                         local-only libraries).
    var drawerActions = isData
      ? '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-reinstall="' + _esc(t.id) + '">↺ Force re-install</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-export-data="' + _esc(t.id) + '">📤 Export</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_danger" data-eli-tm-uninstall="' + _esc(t.id) + '">🗑 Uninstall</button>'
      : '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-vis="' + _esc(t.id) + '">' +
          (t.hidden ? "👁 Show on dashboard" : "🚫 Hide from dashboard") +
        '</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-reinstall="' + _esc(t.id) + '">↺ Force re-install</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_secondary" data-eli-tm-export="' + _esc(t.id) + '">📤 Export</button>' +
        '<button class="_eli3_tm_action_btn _eli3_tm_action_danger" data-eli-tm-uninstall="' + _esc(t.id) + '">🗑 Uninstall</button>';
    var labelTag = isData
      ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_data">DATA</span>' +
        (t.sourceTag === "ENCRYPTED" ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_encrypted">ENCRYPTED</span>'
         : t.sourceTag === "LOCAL"   ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_local">LOCAL</span>'
         : '')
      : ((!t.isV3 ? ' <span class="_eli3_tm_row_tag">V2</span>' : '') +
         (t.core ? ' <span class="_eli3_tm_row_tag _eli3_tm_row_tag_core">CORE</span>' : ''));
    r.innerHTML =
      '<div class="_eli3_tm_row_main">' +
        '<div class="_eli3_tm_row_icon">' + _esc(t.icon) + '</div>' +
        '<div class="_eli3_tm_row_info">' +
          '<div class="_eli3_tm_row_label">' + _esc(t.label) + labelTag + '</div>' +
          '<div class="_eli3_tm_row_meta">' + _esc(t.id) + ' · ' + _shortTs(t.releasedAt) +
            (typeof t.rowCount === "number"
              ? ' · ' + t.rowCount.toLocaleString() + ' row' + (t.rowCount === 1 ? '' : 's')
              : '') +
          '</div>' +
        '</div>' +
        '<div class="_eli3_tm_row_actions">' + rightSide + '</div>' +
      '</div>' +
      '<div class="_eli3_tm_row_drawer" data-eli-tm-drawer="' + _esc(t.id) + '" hidden>' +
        drawerActions +
      '</div>';
    r.setAttribute("data-eli-tm-kind", t.kind || "tool");
    return r;
  }

  mount.appendChild(root);

  // Wire row interactions via event delegation on listWrap
  listWrap.addEventListener("change", function (e) {
    var cb = e.target.closest && e.target.closest("[data-eli-tm-enable]");
    if (cb) {
      var id = cb.getAttribute("data-eli-tm-enable");
      onToggleEnabled(id, cb.checked);
    }
  });
  listWrap.addEventListener("click", function (e) {
    var t = e.target;
    var k = t.closest && t.closest("[data-eli-tm-kebab]");
    if (k) {
      var id = k.getAttribute("data-eli-tm-kebab");
      var drawer = listWrap.querySelector('[data-eli-tm-drawer="' + id + '"]');
      if (drawer) drawer.hidden = !drawer.hidden;
      return;
    }
    // Bundle row interactions.
    var bk = t.closest && t.closest("[data-eli-tm-bundle-kebab]");
    if (bk) {
      var bid = bk.getAttribute("data-eli-tm-bundle-kebab");
      var bDrawer = listWrap.querySelector('[data-eli-tm-bundle-drawer="' + bid + '"]');
      if (bDrawer) bDrawer.hidden = !bDrawer.hidden;
      return;
    }
    var bi = t.closest && t.closest("[data-eli-tm-bundle-install]");
    if (bi) { (opts.onBundleInstall || function(){})(bi.getAttribute("data-eli-tm-bundle-install")); return; }
    var br = t.closest && t.closest("[data-eli-tm-bundle-reinstall]");
    if (br) { (opts.onBundleReinstall || function(){})(br.getAttribute("data-eli-tm-bundle-reinstall")); return; }
    var bu = t.closest && t.closest("[data-eli-tm-bundle-uninstall]");
    if (bu) { (opts.onBundleUninstall || function(){})(bu.getAttribute("data-eli-tm-bundle-uninstall")); return; }
    // Per-row interactions.
    var v = t.closest && t.closest("[data-eli-tm-vis]");
    if (v) { onToggleHidden(v.getAttribute("data-eli-tm-vis")); return; }
    var r = t.closest && t.closest("[data-eli-tm-reinstall]");
    if (r) { onForceReinstall(r.getAttribute("data-eli-tm-reinstall")); return; }
    var x = t.closest && t.closest("[data-eli-tm-export]");
    if (x) { onExport(x.getAttribute("data-eli-tm-export")); return; }
    var xd = t.closest && t.closest("[data-eli-tm-export-data]");
    if (xd) { (opts.onExportData || function(){})(xd.getAttribute("data-eli-tm-export-data")); return; }
    var u = t.closest && t.closest("[data-eli-tm-uninstall]");
    if (u) { onUninstall(u.getAttribute("data-eli-tm-uninstall")); return; }
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["tool_manager"];
  var analyze = bundle && bundle._eliEngineFns && bundle._eliEngineFns.analyze;
  var renderManagerPanel = bundle && bundle._eliViewFns && bundle._eliViewFns.renderManagerPanel;
  var renderReinstallPicker = bundle && bundle._eliViewFns && bundle._eliViewFns.renderReinstallPicker;
  var renderMasterExportPicker = bundle && bundle._eliViewFns && bundle._eliViewFns.renderMasterExportPicker;
  if (!analyze || !renderManagerPanel) {
    eli.log.event("tool", "tool_manager_load_failed", { hasEngine: !!analyze, hasView: !!renderManagerPanel });
    return;
  }

  // 2026-05-12 r2: updateAll / installOne / progress overlay restored to
  // kernel §17.1 to break the bootstrap chicken/egg (Downloads dialog
  // needed updateAll before tool_manager's new boot-tier bundle was in
  // IDB). This tool no longer installs them — kernel owns the canonical
  // version. Keeping this comment so the next maintainer doesn't re-move.

  // Menu-visibility map — consolidated IDB row replacing the v2-era
  // per-category `eli_menuvis_<catId>` localStorage keys. One row at
  // STORE_CONFIG._menu_visibility carries the whole map. First read
  // lazy-migrates legacy localStorage entries (scan v2Keys-style for
  // any `eli_menuvis_*` keys, copy values, delete originals).
  var _menuVisMap = {};
  var _menuVisLoaded = false;
  function _loadMenuVis() {
    if (_menuVisLoaded) return Promise.resolve(_menuVisMap);
    return eli.storage.get("config", "_menu_visibility").then(function (row) {
      if (row && row.map && typeof row.map === "object") {
        _menuVisMap = row.map;
        _menuVisLoaded = true;
        return _menuVisMap;
      }
      // No IDB row — try to migrate from legacy localStorage.
      try {
        for (var i = 0; i < localStorage.length; i++) {
          var k = localStorage.key(i);
          if (!k || k.indexOf("eli_menuvis_") !== 0) continue;
          var catId = k.substring("eli_menuvis_".length);
          var v = localStorage.getItem(k);
          if (v === "show" || v === "hide") _menuVisMap[catId] = v;
        }
      } catch (e) { /* tolerate */ }
      _menuVisLoaded = true;
      // Persist migrated map + clear legacy keys.
      if (Object.keys(_menuVisMap).length) {
        eli.storage.put("config", { key: "_menu_visibility", map: _menuVisMap })
          .then(function () {
            try {
              Object.keys(_menuVisMap).forEach(function (catId) {
                localStorage.removeItem("eli_menuvis_" + catId);
              });
            } catch (e) { /* tolerate */ }
          }).catch(function () {});
      }
      return _menuVisMap;
    }).catch(function () { _menuVisLoaded = true; return _menuVisMap; });
  }
  function _setMenuVis(catId, value) {
    _menuVisMap[catId] = value;
    eli.storage.put("config", { key: "_menu_visibility", map: _menuVisMap })
      .catch(function () { /* tolerate */ });
  }

  var providers = {
    tools: eli.tools,
    compat: eli.compat,
    storage: eli.storage,
    menuVis: _menuVisMap,
  };

  function _isDataId(id) { return /^_data_|^__data_/.test(String(id || "")); }

  // Look up a row's metadata from the latest analyze result. Used by
  // uninstall + force-reinstall to detect non-CDN libraries (cdnTracked
  // === false) which can't auto-recover and need re-import instead.
  var _lastResult = null;
  function _findRow(id) {
    if (!_lastResult || !_lastResult.items) return null;
    for (var i = 0; i < _lastResult.items.length; i++) {
      if (_lastResult.items[i].id === id) return _lastResult.items[i];
    }
    return null;
  }

  // _showReinstallSummary — single dialog summarizing what landed after
  // a force-reinstall / sync. Replaces per-bundle toasts that piled up
  // unreadably. Falls back to a minimal "done" dialog if the sync result
  // doesn't carry installed/updated/failed arrays (it does when called
  // via updateAll, doesn't when called via syncFromManifest's data-only
  // auto-install path — both are tolerated).
  function _showReinstallSummary(label, sync) {
    if (typeof showEliDialog !== "function") {
      // Fallback: nothing visible if showEliDialog isn't around. Don't
      // toast — the whole point is to avoid that.
      return;
    }
    // updateAll now pushes {label, kind} objects (kernel ≥ 2026-05-12);
    // older kernels pushed bare label strings. Normalize so .join(", ")
    // produces readable text on either shape.
    function _label(x) { return typeof x === "string" ? x : (x && x.label) || ""; }
    var installed = ((sync && sync.installed) || []).map(_label);
    var updated   = ((sync && sync.updated)   || []).map(_label);
    var failed    = ((sync && sync.failed)    || []).map(_label);
    var totalOk = installed.length + updated.length;
    var paragraphs = [];
    if (label) paragraphs.push("Reinstall complete: <b>" + label + "</b>");
    if (totalOk === 0 && !failed.length) {
      paragraphs.push("CDN sync ran with no changes (already up to date).");
    } else {
      var lines = [];
      if (installed.length) lines.push("📦 Installed " + installed.length + ": " + installed.join(", "));
      if (updated.length)   lines.push("⬆️ Updated " + updated.length + ": " + updated.join(", "));
      if (failed.length)    lines.push("⚠️ Failed " + failed.length + ": " + failed.join(", "));
      paragraphs.push(lines.join("<br>"));
    }
    showEliDialog({
      variant: failed.length ? "warning" : "success",
      icon: failed.length ? "⚠️" : "✓",
      title: "Force re-install",
      paragraphs: paragraphs,
      secondary: { label: "Close" },
    });
  }

  // Bundle action — install / reinstall / uninstall a manifest-defined
  // bundle (group of tools + data libs treated as one unit).
  //   install   = install members that aren't installed yet (skip ones
  //               already present); triggers syncFromManifest with
  //               force:false so deltas only.
  //   reinstall = uninstall + force-resync ALL members (clean slate).
  //   uninstall = remove every member from this device.
  function _bundleAction(bundleId, action) {
    var bundle = _lastResult && (_lastResult.bundles || []).find(function (b) { return b.id === bundleId; });
    if (!bundle) { showToast("Bundle not found.", "err"); return; }
    var verb = action === "install" ? "Install" : action === "reinstall" ? "Force-reinstall" : "Uninstall";
    var msg = action === "install"
      ? "Installs " + bundle.totalCount + " items: " + bundle.totalCount + " tool/data members. Already-installed members are skipped."
      : action === "reinstall"
        ? "Wipes and re-fetches all " + bundle.totalCount + " members from CDN. Clean slate."
        : "Removes all " + bundle.totalCount + " members from this device. Click Check for Updates to bring CDN-tracked items back.";
    eli.events.safeAsync(eli.ui.confirm({
      title: verb + " bundle: " + bundle.label + "?",
      message: msg,
      confirmLabel: verb,
    }), "tool_manager.bundle_action.confirm").then(function (ok) {
      if (!ok) return;
      var memberIds = bundle.members.map(function (m) { return m.id; });
      var ops;
      if (action === "uninstall") {
        ops = memberIds.map(function (id) {
          return _isDataId(id)
            ? eli.tools.uninstallData(id).catch(function () {})
            : eli.tools.uninstall(id).catch(function () {});
        });
        eli.events.safeAsync(Promise.all(ops), "tool_manager.bundle_uninstall.run").then(function () {
          showToast("✓ Uninstalled bundle: " + bundle.label, "ok");
          if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          _show();
        });
        return;
      }
      // install / reinstall both end with syncFromManifest.
      var pre = action === "reinstall"
        ? Promise.all(memberIds.map(function (id) {
            return _isDataId(id)
              ? eli.tools.uninstallData(id).catch(function () {})
              : eli.tools.uninstall(id).catch(function () {});
          }))
        : Promise.resolve();
      eli.events.safeAsync(
        pre.then(function () { return eli.tools.syncFromManifest({ force: true }); }),
        "tool_manager.bundle_action.run"
      ).then(function (sync) {
        _showReinstallSummary(bundle.label + " (" + verb + ")", sync);
        if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
        _show();
      });
    });
  }

  // Legacy all-or-nothing reinstall — fallback when picker view isn't bundled.
  function _reinstallAllLegacy() {
    eli.events.safeAsync(eli.ui.confirm({
      title: "Re-install everything?",
      message: "Forces a fresh CDN pull for every installed tool AND data library.",
      confirmLabel: "Re-install all",
    }), "tool_manager.reinstall_all.confirm").then(function (ok) {
      if (!ok) return;
      eli.events.safeAsync(
        Promise.all([eli.tools.list(), eli.tools.listData ? eli.tools.listData() : Promise.resolve([])]),
        "tool_manager.reinstall_all.list"
      ).then(function (rs) {
        var toolIds = (rs[0] || [])
          .filter(function (t) { return t && t.id && String(t.id).charAt(0) !== "_"; })
          .map(function (t) { return t.id; });
        var dataIds = (rs[1] || []).map(function (d) { return d.id; });
        var total = toolIds.length + dataIds.length;
        if (!total) { showToast("Nothing installed.", "info"); return; }
        var ops = toolIds.map(function (id) { return eli.tools.uninstall(id).catch(function () {}); })
          .concat(dataIds.map(function (id) { return eli.tools.uninstallData(id).catch(function () {}); }));
        Promise.all(ops).then(function () { return eli.tools.syncFromManifest({ force: true }); })
          .then(function (sync) { _showReinstallSummary("Re-install all (" + total + " bundles)", sync); _show(); });
      });
    });
  }

  // One-shot cleanup of stale legacy data stamps (camelCase residues whose
  // snake_case canonical equivalent is also installed). Deletes ONLY the
  // STORE_CONFIG stamp — never touches section rows, since those belong to
  // the canonical install. Best-effort; failures are tolerated.
  function _pruneRedundantLegacyStamps(ids) {
    if (!ids || !ids.length) return;
    ids.forEach(function (id) {
      var key = "_data_" + id;
      eli.storage.delete("config", key).then(function () {
        try { eli.compat.lsRemove("eli_dataVer_" + id); } catch (e) {}
        try { eli.compat.lsRemove("eli_dataReleasedAt_" + id); } catch (e) {}
        eli.log.event("tool_manager", "legacy_stamp_pruned", { id: id });
      }).catch(function () { /* tolerate */ });
    });
  }

  function _show() {
    eli.events.safeAsync(_loadMenuVis(), "tool_manager.menuvis_load").then(function () {
    eli.events.safeAsync(analyze({}, providers), "tool_manager.analyze").then(function (result) {
      if (!result) return;
      _lastResult = result;
      // Persist the dedupe — drop stale STORE_CONFIG stamps so subsequent
      // opens (and any other consumer of listData()) don't see duplicates.
      _pruneRedundantLegacyStamps(result.redundantLegacyDataIds);
      // Same helper for phantom data stamps that resolve to STORE_JSON_TOOLS.
      // Stamp-only delete — _pruneRedundantLegacyStamps never wipes section
      // data, so an old _data_jsonTools artifact disappears without touching
      // the user's installed tool bundles.
      _pruneRedundantLegacyStamps(result.phantomToolDataIds);
      renderManagerPanel({
        result: result,
        mount: document.getElementById("_eli3_dashboard_root"),
        onClose: function () {
          if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
        },
        onToggleEnabled: eli.events.guard(function (id, enabled) {
          var p = enabled ? eli.tools.enable(id) : eli.tools.disable(id);
          eli.events.safeAsync(p, "tool_manager.toggle").then(function () {
            showToast((id) + (enabled ? " enabled" : " disabled"), "ok");
            if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          });
        }, "tool_manager.toggle"),
        onToggleHidden: eli.events.guard(function (id) {
          var current = _menuVisMap[id] || "";
          var next = current === "hide" ? "show" : "hide";
          _setMenuVis(id, next);
          providers.menuVis = _menuVisMap; // keep providers ref fresh
          showToast((next === "hide" ? "Hidden " : "Shown ") + id, "ok");
          if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
          _show(); // re-render with updated state
        }, "tool_manager.visibility"),
        onForceReinstall: eli.events.guard(function (id) {
          var isData = _isDataId(id);
          var row = _findRow(id);
          var isLocalLib = isData && row && row.cdnTracked === false;
          // Local (encrypted / manually imported) libraries can't be
          // auto-fetched — route to the import dialog instead.
          if (isLocalLib) {
            eli.events.safeAsync(eli.ui.confirm({
              title: "Re-import " + id + "?",
              message: "This library was imported manually (encrypted credentials or JSON upload). Force-refresh isn't possible from CDN. Want to open the import dialog now?",
              confirmLabel: "Open import",
            }), "tool_manager.local_lib_reimport").then(function (ok) {
              if (!ok) return;
              if (eli.settings && eli.settings.importToken) {
                eli.settings.importToken({ title: "Re-import " + id });
              } else if (eli.settings && eli.settings.importPackage) {
                eli.settings.importPackage();
              } else {
                showToast("Import dialog unavailable.", "err");
              }
            });
            return;
          }
          eli.events.safeAsync(eli.ui.confirm({
            title: "Force re-install " + id + "?",
            message: "Removes the local copy and downloads fresh from CDN.",
          }), "tool_manager.reinstall.confirm").then(function (ok) {
            if (!ok) return;
            var clearStep = isData ? eli.tools.uninstallData(id) : eli.tools.uninstall(id);
            eli.events.safeAsync(
              clearStep.then(function () { return eli.tools.syncFromManifest({ force: true }); }),
              "tool_manager.reinstall"
            ).then(function (sync) {
              // Single summary dialog instead of per-bundle toasts.
              // syncFromManifest returns {installed: [], updated: [], failed: []}
              // when called via updateAll path. The reinstall path uses the
              // missing/updates split, so we fall back to a generic "done".
              _showReinstallSummary(id, sync);
              _show();
            });
          });
        }, "tool_manager.reinstall"),
        onExport: eli.events.guard(function (id) {
          eli.events.safeAsync(eli.tools.get(id), "tool_manager.export.get").then(function (b) {
            if (!b) return;
            var json = JSON.stringify({
              schemaVersion: 1,
              releasedAt: b.releasedAt || new Date().toISOString(),
              sections: { jsonTools: [b] },
            }, null, 2);
            try {
              navigator.clipboard.writeText(json);
              showToast("Copied " + id + " JSON to clipboard.", "ok");
            } catch (e) {
              showToast("Clipboard unavailable.", "warn");
            }
          });
        }, "tool_manager.export"),
        // Export one data library to a downloadable JSON file. Shape
        // matches installFromText's data-bundle detection ({sections,
        // sectionVersions}) so the user can re-import via Import Package
        // for round-trip backup/restore. Encrypted libraries export
        // their DECRYPTED IDB rows — the cipher protects the bundle
        // file in transit, not the local rows.
        onExportData: eli.events.guard(function (id) {
          _exportDataBundle(id);
        }, "tool_manager.export_data"),
        onBundleInstall: eli.events.guard(function (bundleId) {
          _bundleAction(bundleId, "install");
        }, "tool_manager.bundle_install"),
        onBundleReinstall: eli.events.guard(function (bundleId) {
          _bundleAction(bundleId, "reinstall");
        }, "tool_manager.bundle_reinstall"),
        onBundleUninstall: eli.events.guard(function (bundleId) {
          _bundleAction(bundleId, "uninstall");
        }, "tool_manager.bundle_uninstall"),
        onUninstall: eli.events.guard(function (id) {
          var isData = _isDataId(id);
          var row = _findRow(id);
          var isLocalLib = isData && row && row.cdnTracked === false;
          // Plain uninstall (no auto-sync). User clicks Check for Updates
          // to bring CDN-tracked items back. Local libraries lose their
          // data permanently and need re-import to restore.
          var msg = !isData
            ? "Removes the bundle from this device. Click Check for Updates to reinstall."
            : isLocalLib
              ? "⚠️ Wipes ALL rows in this library and removes it from this device. This library was imported manually — Check for Updates can't bring it back. You'll need to re-import the source file (encrypted bundle or JSON)."
              : "Wipes ALL rows in this library and removes it from this device. Click Check for Updates to redownload from CDN.";
          eli.events.safeAsync(eli.ui.confirm({
            title: "Uninstall " + id + "?",
            message: msg,
            confirmLabel: "Uninstall",
          }), "tool_manager.uninstall.confirm").then(function (ok) {
            if (!ok) return;
            var op = isData ? eli.tools.uninstallData(id) : eli.tools.uninstall(id);
            eli.events.safeAsync(op, "tool_manager.uninstall").then(function () {
              showToast("Uninstalled " + id, "ok");
              if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
              _show();
            });
          });
        }, "tool_manager.uninstall"),
        onCheckUpdates: eli.events.guard(function () {
          eli.events.safeAsync(eli.tools.syncFromManifest({ force: true }), "tool_manager.check").then(function (sync) {
            if (eli.dashboard && eli.dashboard.showDownloadsDialog) {
              eli.dashboard.showDownloadsDialog(sync);
            }
          });
        }, "tool_manager.check"),
        onImport: eli.events.guard(function () {
          if (eli.settings && eli.settings.importPackage) eli.settings.importPackage();
        }, "tool_manager.import"),
        onReinstallAll: eli.events.guard(function () {
          if (!renderReinstallPicker) {
            // Fallback to the old all-or-nothing flow if the picker view
            // isn't bundled (e.g. older tool_manager build).
            return _reinstallAllLegacy();
          }
          // Filter: skip kernel-internal tool metadata rows (_meta,
          // __enabled), but KEEP data libraries — their IDs all start
          // with __data_ which is intentional, not internal metadata.
          var rows = (result.items || []).filter(function (r) {
            if (!r || !r.id) return false;
            if (r.kind === "tool" && String(r.id).charAt(0) === "_") return false;
            return true;
          });
          renderReinstallPicker({
            rows: rows,
            onCancel: function () {},
            onConfirm: function (ids) {
              if (!ids || !ids.length) { showToast("Nothing selected.", "info"); return; }
              var ops = ids.map(function (id) {
                return _isDataId(id) ? eli.tools.uninstallData(id).catch(function () {})
                                     : eli.tools.uninstall(id).catch(function () {});
              });
              eli.events.safeAsync(
                Promise.all(ops).then(function () { return eli.tools.syncFromManifest({ force: true }); }),
                "tool_manager.reinstall_picked"
              ).then(function (sync) {
                _showReinstallSummary("Re-install picked (" + ids.length + " bundle" + (ids.length === 1 ? "" : "s") + ")", sync);
                if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
                _show();
              });
            },
          });
        }, "tool_manager.reinstall_all"),
        onExportMaster: eli.events.guard(function () {
          if (!renderMasterExportPicker) {
            showToast("Export dialog not available — old bundle.", "warn");
            return;
          }
          var rows = (result.items || []).filter(function (r) {
            if (!r || !r.id) return false;
            if (r.kind === "tool" && String(r.id).charAt(0) === "_") return false;
            return true;
          });
          renderMasterExportPicker({
            rows: rows,
            onCancel: function () {},
            onConfirm: function (picks) {
              _exportMasterJson(picks);
            },
          });
        }, "tool_manager.export_master"),
      });
    });
    });
  }

  // Build a master export JSON from the user's selection. Shape matches
  // a subset of the v2 master JSON: { schemaVersion, exportedAt, kind,
  // tools: {id: bundle}, data: {section: [rows]} }. Writes to clipboard
  // — same delivery as Refresh ELI to dodge Office Add-in iframe download
  // restrictions. Manifest sections are looked up to know which IDB
  // stores each data lib populates.
  var _SECTION_ALIASES = {
    jsonTools: "json_tools",
    agreementTypes: "agreement_types",
    riskRules: "risk_rules",
    emailTemplates: "email_templates",
    loadingMsgs: "loading_msgs",
    cleanerRules: "cleaner_rules",
    execBriefTerms: "exec_brief_terms",
    teamCommentary: "team_commentary",
    bdTemplates: "bd_templates",
  };
  function _resolveStore(name) { return _SECTION_ALIASES[name] || name; }

  // Per-library export — produces a single-id data bundle in the shape
  // installFromText accepts (`{sections, sectionVersions}`). Downloads as
  // <id>-export-YYYY-MM-DD.json. Section names + versions are pulled from
  // the cached manifest so the re-import lands in the same IDB stores
  // with the same version stamps.
  function _exportDataBundle(id) {
    if (!id) return;
    showToast("⏳ Bundling " + id + "…", "info");
    var manifestP = eli.tools.getCachedManifest
      ? eli.tools.getCachedManifest().catch(function () { return null; })
      : Promise.resolve(null);
    manifestP.then(function (manifest) {
      var entry = null;
      if (manifest && Array.isArray(manifest.tools)) {
        entry = manifest.tools.find(function (e) { return e.id === id; });
      }
      var sections = (entry && Array.isArray(entry.sections)) ? entry.sections : [];
      if (!sections.length) {
        // Fallback for legacy / locally-imported libs not in the manifest:
        // derive store name from the id (mirrors uninstallData's fallback).
        var derived = String(id).replace(/^__data_/, "").replace(/^_data_/, "");
        if (derived) sections = [derived];
      }
      if (!sections.length) {
        showToast("Couldn't resolve sections for " + id, "err");
        return null;
      }
      var versions = (entry && entry.sectionVersions) || {};
      var perSection = sections.map(function (s) {
        var store = _resolveStore(s);
        return eli.storage.getAll(store).catch(function () { return []; })
          .then(function (rows) { return { section: s, rows: rows || [] }; });
      });
      return Promise.all(perSection).then(function (results) {
        var outSections = {};
        var outVersions = {};
        var rowCount = 0;
        results.forEach(function (r) {
          outSections[r.section] = r.rows;
          rowCount += r.rows.length;
          if (versions[r.section] != null) outVersions[r.section] = versions[r.section];
        });
        // installFromText requires non-empty sectionVersions — if the
        // manifest didn't carry one for this section, stamp the entry's
        // top-level version (or fall back to 1) so the re-import path
        // still detects it as a data bundle and not "unknown shape".
        if (!Object.keys(outVersions).length) {
          var stamp = (entry && entry.version) || 1;
          Object.keys(outSections).forEach(function (s) { outVersions[s] = stamp; });
        }
        return {
          schemaVersion: 1,
          kind: "eli_data_export",
          id: id,
          exportedAt: new Date().toISOString(),
          releasedAt: (entry && entry.releasedAt) || null,
          version: (entry && entry.version) || null,
          sectionVersions: outVersions,
          sections: outSections,
          rowCount: rowCount,
        };
      });
    }).then(function (bundle) {
      if (!bundle) return;
      var json = JSON.stringify(bundle, null, 2);
      var stamp = new Date().toISOString().slice(0, 10);
      var safeId = String(id).replace(/[^a-z0-9_-]/gi, "_");
      _downloadJson(safeId + "-export-" + stamp + ".json", json);
      showToast("✅ Exported " + id + " · " + bundle.rowCount + " row" +
        (bundle.rowCount === 1 ? "" : "s"), "ok");
    }).catch(function (err) {
      showToast("Export failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // Trigger a browser download for a JSON blob. Office.js taskpane allows
  // <a href=blob: download> in modern Word; we revoke the URL after the
  // click to free memory.
  function _downloadJson(filename, jsonText) {
    try {
      var blob = new Blob([jsonText], { type: "application/json" });
      var url = URL.createObjectURL(blob);
      var a = document.createElement("a");
      a.href = url;
      a.download = filename;
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      setTimeout(function () {
        try { document.body.removeChild(a); } catch (_) {}
        try { URL.revokeObjectURL(url); } catch (_) {}
      }, 0);
    } catch (e) {
      // Sandboxed iframe blocked the download — fall back to clipboard so
      // the user can still capture the export by pasting elsewhere.
      _writeClipboard(jsonText).then(function () {
        showToast("Download blocked — copied " + filename + " to clipboard instead.", "warn");
      }).catch(function () {
        showToast("Download + clipboard both blocked. Open the console: __lastExport.", "err");
        try { window.__lastExport = jsonText; } catch (_) {}
      });
    }
  }

  function _exportMasterJson(picks) {
    picks = picks || { tools: [], data: [] };
    if (!picks.tools.length && !picks.data.length) {
      showToast("Nothing selected.", "info");
      return;
    }
    showToast("⏳ Bundling export…", "info");
    var manifestP = eli.tools.getCachedManifest ? eli.tools.getCachedManifest().catch(function () { return null; }) : Promise.resolve(null);
    manifestP.then(function (manifest) {
      var manifestById = {};
      if (manifest && Array.isArray(manifest.tools)) {
        manifest.tools.forEach(function (e) { manifestById[e.id] = e; });
      }
      var toolPromises = picks.tools.map(function (id) {
        return eli.tools.get(id).catch(function () { return null; })
          .then(function (b) { return { id: id, bundle: b }; });
      });
      // For each picked data lib, find its manifest sections and load each store.
      var dataPromises = picks.data.map(function (id) {
        var entry = manifestById[id];
        var sections = (entry && Array.isArray(entry.sections)) ? entry.sections : [];
        if (!sections.length) {
          var derived = String(id).replace(/^__data_/, "");
          if (derived) sections = [derived];
        }
        var perSection = sections.map(function (s) {
          var store = _resolveStore(s);
          return eli.storage.getAll(store).catch(function () { return []; })
            .then(function (rows) { return { section: s, rows: rows || [] }; });
        });
        return Promise.all(perSection).then(function (results) {
          return { id: id, sections: results };
        });
      });
      return Promise.all([Promise.all(toolPromises), Promise.all(dataPromises)]);
    }).then(function (results) {
      var toolResults = results[0] || [];
      var dataResults = results[1] || [];
      var out = {
        schemaVersion: 1,
        kind: "eli_master_export",
        exportedAt: new Date().toISOString(),
        tools: {},
        data: {},
      };
      var toolCount = 0, rowCount = 0;
      toolResults.forEach(function (r) {
        if (r && r.bundle) { out.tools[r.id] = r.bundle; toolCount++; }
      });
      dataResults.forEach(function (r) {
        if (!r || !Array.isArray(r.sections)) return;
        r.sections.forEach(function (s) {
          out.data[s.section] = (out.data[s.section] || []).concat(s.rows);
          rowCount += s.rows.length;
        });
      });
      var json = JSON.stringify(out, null, 2);
      var doneToast = "✅ Master export copied · " + toolCount + " tool" + (toolCount === 1 ? "" : "s") +
        " · " + Object.keys(out.data).length + " section" + (Object.keys(out.data).length === 1 ? "" : "s") +
        " · " + rowCount + " row" + (rowCount === 1 ? "" : "s");
      _writeClipboard(json).then(function () {
        showToast(doneToast, "ok");
      }).catch(function (err) {
        showToast("Clipboard write failed: " + (err && err.message || "unknown"), "err");
      });
    }).catch(function (err) {
      showToast("Export failed: " + (err && err.message || "unknown"), "err");
    });
  }

  // Clipboard write with textarea fallback for sandboxed iframes — same
  // helper refresh_eli uses. Self-contained so tool_manager doesn't need
  // a kernel surface for clipboard primitives.
  function _writeClipboard(text) {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      return navigator.clipboard.writeText(text).catch(function () {
        return _writeClipboardFallback(text);
      });
    }
    return _writeClipboardFallback(text);
  }
  function _writeClipboardFallback(text) {
    return new Promise(function (resolve, reject) {
      var ta = document.createElement("textarea");
      ta.value = text;
      ta.style.cssText = "position:fixed;left:-9999px;opacity:0";
      document.body.appendChild(ta);
      ta.select();
      var ok = false;
      try { ok = document.execCommand("copy"); } catch (e) {}
      document.body.removeChild(ta);
      ok ? resolve() : reject(new Error("clipboard copy blocked"));
    });
  }

  eli.register({
    tile: { app_tool_manager: _show },
  });

  eli.log.event("tool", "tool_manager_initialized", {});
}

jsonTools.css:
/* tool_manager v3 — full-takeover panel. Injected as <style data-tool="tool_manager">. */

/* Kill parent scrollbars while tool_manager is mounted. The kernel's
 * `#output` and `#_eli3_dashboard_root` both run `overflow-y: auto`,
 * which gives a second scrollbar nested outside `_eli3_tm_list`'s own
 * scroll. Force them to clip — the list is the only thing that should
 * scroll. Uses :has() (Office WebView is modern Chromium). */
body:has(._eli3_tm_root) #output,
body:has(._eli3_tm_root) #_eli3_dashboard_root {
  overflow: hidden !important;
}

._eli3_tm_root {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  box-sizing: border-box;
  background: #fff;
  overflow: hidden;
}
/* Standard tool-hub header — dark navy banner with gold accent rule.
   Matches build_draft + Save panel + cross-tool standard. */
._eli3_tm_bar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  border-bottom: 3px solid #c9a227;
}
._eli3_tm_back {
  background: none; border: none; cursor: pointer;
  font: 400 22px/1 'Inter', sans-serif; color: #cbd5e1;
  padding: 0 4px;
  transition: color 0.15s;
}
._eli3_tm_back:hover { color: #f2d866; }
._eli3_tm_title {
  font: 800 16px/1.2 'Georgia', serif;
  color: #ffffff;
  letter-spacing: 0.2px;
  flex: 1;
}
._eli3_tm_overview {
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #c9a227;
  background: rgba(201,162,39,0.15);
  border: 1px solid rgba(201,162,39,0.4);
  padding: 5px 10px;
  border-radius: 12px;
}

._eli3_tm_actions {
  display: flex; gap: 8px;
  padding: 12px 14px 0;
}
._eli3_tm_action_btn {
  flex: 1;
  padding: 8px 14px;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff; border: 1px solid rgba(0,0,0,0.1);
  cursor: pointer;
  transition: transform .12s, box-shadow .12s;
}
._eli3_tm_action_btn:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(21,101,192,0.3); }
._eli3_tm_action_btn._eli3_tm_action_secondary {
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #546e7a; border: 1px solid #b0bec5;
  text-shadow: 0 1px 0 rgba(255,255,255,0.8);
}
._eli3_tm_action_btn._eli3_tm_action_secondary:hover {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0; border-color: #90caf9;
}
._eli3_tm_action_btn._eli3_tm_action_danger {
  background: linear-gradient(135deg, #ef4444 0%, #b91c1c 100%);
  color: #fff; border: 1px solid #b91c1c;
}
._eli3_tm_action_btn._eli3_tm_action_danger:hover { transform: translateY(-1px); box-shadow: 0 4px 10px rgba(239,68,68,0.3); }

._eli3_tm_list {
  flex: 1; overflow-y: auto;
  padding: 12px 14px 18px;
}
._eli3_tm_empty {
  text-align: center; padding: 30px 0;
  font: 600 12px/1.4 'Inter', sans-serif; color: #94a3b8;
}
._eli3_tm_cat_head {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #475569;
  margin: 14px 0 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_cat_head:first-child { margin-top: 0; }
._eli3_tm_row {
  border: 1px solid #e2e8f0;
  background: #fff;
  margin-bottom: 6px;
  transition: border-color .15s, background .15s;
}
._eli3_tm_row:hover { border-color: #cbd5e1; }
._eli3_tm_row_disabled { opacity: 0.55; }
._eli3_tm_row_main {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 12px;
}
._eli3_tm_row_icon { font-size: 22px; line-height: 1; flex-shrink: 0; }
._eli3_tm_row_info { flex: 1; min-width: 0; }
._eli3_tm_row_label {
  font: 700 13px/1.3 'Inter', sans-serif;
  color: #0f172a;
}
._eli3_tm_row_tag {
  display: inline-block;
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: #fef3c7; color: #92400e;
  padding: 2px 5px;
  margin-left: 6px;
  vertical-align: 1px;
}
._eli3_tm_row_tag_core { background: #dbeafe; color: #1e3a8a; }
._eli3_tm_row_tag_data { background: #ede9fe; color: #5b21b6; }
._eli3_tm_row_meta {
  font: 600 10px/1.3 'JetBrains Mono', monospace;
  color: #94a3b8;
  margin-top: 2px;
}
._eli3_tm_row_actions {
  display: flex; gap: 8px; align-items: center;
}
._eli3_tm_kebab {
  background: none; border: none; cursor: pointer;
  font: 700 16px/1 'Inter', sans-serif;
  color: #64748b; padding: 4px 8px;
}
._eli3_tm_kebab:hover { color: #0f172a; }
._eli3_tm_row_drawer[hidden] { display: none; }
._eli3_tm_row_drawer {
  display: flex; flex-wrap: wrap; gap: 6px;
  padding: 10px 12px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
}
._eli3_tm_row_drawer ._eli3_tm_action_btn { flex: 1 1 auto; min-width: 120px; }

/* Toggle switch (mirrors settings toggle pattern). */
._eli3_tm_toggle { display: inline-flex; align-items: center; cursor: pointer; user-select: none; }
._eli3_tm_toggle input[type="checkbox"] { position: absolute; opacity: 0; pointer-events: none; }
._eli3_tm_toggle_slider {
  width: 32px; height: 16px; background: #cbd5e1;
  position: relative; transition: background 0.15s; display: inline-block;
}
._eli3_tm_toggle_slider::after {
  content: ""; position: absolute; top: 2px; left: 2px;
  width: 12px; height: 12px; background: #fff; transition: left 0.15s;
}
._eli3_tm_toggle input:checked + ._eli3_tm_toggle_slider { background: #1565c0; }
._eli3_tm_toggle input:checked + ._eli3_tm_toggle_slider::after { left: 18px; }

/* Dark mode */

@media (max-width: 380px) {
  ._eli3_tm_action_btn { font-size: 10px; padding: 7px 8px; }
  ._eli3_tm_row_tag { display: none; }
}

/* LOCAL tag — non-CDN, non-encrypted (one-off manual JSON upload). */
._eli3_tm_row_tag_local {
  background: #fef3c7; color: #b45309; border: 1px solid #fbbf24;
}
/* ENCRYPTED tag — installed from a decrypted library envelope. */
._eli3_tm_row_tag_encrypted {
  background: #ede9fe; color: #6d28d9; border: 1px solid #a78bfa;
}

/* =====================================================================
   Force Reinstall picker dialog (premium-tier styling)
   ===================================================================== */
._eli3_tm_pick_dialog ._eli3_dialog_body { padding: 0 !important; }
._eli3_tm_pick_intro {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #475569;
  padding: 14px 18px 10px;
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_pick_quickactions {
  display: flex; gap: 6px;
  padding: 8px 18px;
  background: #f9fafb;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_tm_pick_quick {
  font: 700 9px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
  padding: 6px 11px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_tm_pick_quick:hover {
  background: #3b82f6; color: #fff; border-color: #1d4ed8;
  transform: translateY(-1px);
  box-shadow: 0 2px 4px rgba(59,130,246,0.3);
}
._eli3_tm_pick_section {
  border-bottom: 1px solid #f1f5f9;
}
._eli3_tm_pick_section:last-of-type { border-bottom: none; }
._eli3_tm_pick_section_head {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  margin: 0;
  padding: 10px 18px;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2f6 100%);
  border: none;
  border-bottom: 1px solid #e2e8f0;
  cursor: pointer;
  text-align: left;
  font-family: inherit;
  transition: background 0.15s;
}
._eli3_tm_pick_section_head:hover {
  background: linear-gradient(180deg, #fff 0%, #eff6ff 100%);
}
._eli3_tm_pick_section_chevron {
  font-size: 11px;
  color: #64748b;
  flex: 0 0 auto;
  width: 12px;
  text-align: center;
}
._eli3_tm_pick_section_body {
  padding: 10px 18px 12px;
}
._eli3_tm_pick_section_title {
  font: 800 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.7px;
  color: #0f172a;
}
._eli3_tm_pick_section_count {
  font: 700 10px/1 'Inter', sans-serif;
  /* Lighter royal-blue badge — matches the OARS viewer + Save panel
     headers for cross-UI cohesion. */
  background: #3b82f6; color: #fff;
  padding: 3px 8px;
  border-radius: 10px;
  min-width: 18px;
  text-align: center;
}
._eli3_tm_pick_section_sub {
  font: 400 11px/1.4 'Inter', sans-serif;
  font-style: italic;
  color: #64748b;
  margin-bottom: 6px;
  margin-top: -4px;
}
._eli3_tm_pick_row {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px;
  margin-bottom: 2px;
  font: 500 12px/1.3 'Inter', sans-serif;
  color: #0f172a;
  cursor: pointer;
  border: 1px solid transparent;
  background: #fff;
  transition: all 0.12s;
}
._eli3_tm_pick_row:hover {
  background: #eff6ff;
  border-color: #93c5fd;
}
._eli3_tm_pick_row input[type="checkbox"] {
  flex: 0 0 auto;
  width: 16px; height: 16px;
  accent-color: #3b82f6;
  cursor: pointer;
}
._eli3_tm_pick_row_lock {
  flex: 0 0 16px;
  font-size: 13px;
  text-align: center;
  opacity: 0.6;
}
._eli3_tm_pick_row_icon {
  flex: 0 0 auto;
  font-size: 16px;
  line-height: 1;
}
._eli3_tm_pick_row_label {
  flex: 1 1 auto;
  font-weight: 600;
  color: #0f172a;
  min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
._eli3_tm_pick_id {
  flex: 0 0 auto;
  font: 500 10px/1 monospace;
  color: #64748b;
  background: #f1f5f9;
  padding: 3px 6px;
  border-radius: 3px;
}
._eli3_tm_pick_row_disabled {
  cursor: not-allowed;
  opacity: 0.55;
  background: #fafbfc;
}
._eli3_tm_pick_row_disabled:hover {
  background: #fafbfc;
  border-color: transparent;
}
/* =====================================================================
   Collapsible top-level sections (Bundles / Tools / Data Libraries)
   ===================================================================== */
._eli3_tm_section {
  margin-bottom: 14px;
}
._eli3_tm_section_head {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 10px 14px;
  background: linear-gradient(180deg, #f8fafc 0%, #eef2f6 100%);
  border: 1px solid #cbd5e1;
  cursor: pointer;
  font: 700 12px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  color: #1e293b;
  transition: background 0.15s, border-color 0.15s;
}
._eli3_tm_section_head:hover {
  background: linear-gradient(180deg, #fff 0%, #eff6ff 100%);
  border-color: #93c5fd;
}
._eli3_tm_section_chevron {
  font-size: 11px;
  color: #64748b;
  flex: 0 0 auto;
  width: 12px;
  text-align: center;
}
._eli3_tm_section_title { flex: 1; text-align: left; }
._eli3_tm_section_count {
  flex: 0 0 auto;
  font: 700 10px/1 'Inter', sans-serif;
  background: #1565c0; color: #fff;
  padding: 3px 8px;
  border-radius: 10px;
  min-width: 20px;
  text-align: center;
}
._eli3_tm_section_body {
  padding: 8px 0 0;
}

/* =====================================================================
   Bundle rows (top-level pack list)
   ===================================================================== */
